BEGIN;
SELECT no_plan();
SELECT ok(NOT has_function_privilege('authenticated','public.audit_privileged_write_outcome(text,uuid,text,text)','EXECUTE') AND has_function_privilege('service_role','public.record_worker_audit_outcome(uuid,text,uuid,text,text)','EXECUTE'),'learners cannot call the generic audit writer');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
SELECT set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.audit_privileged_write_outcome('student_attempt_submit','c1111111-1111-4111-8111-111111111111','failed','state_conflict')$$,'42501',NULL,'learner cannot forge a failure for their own attempt');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM private.security_audit_events WHERE actor_id='11111111-1111-4111-8111-111111111111' AND action='student_attempt_submit' AND target_id='c1111111-1111-4111-8111-111111111111' AND outcome='failed'),0,'direct browser calls create no fabricated learner failure event');
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT set_config('request.headers','{"x-request-id":"dddddddd-dddd-4ddd-8ddd-dddddddddddd"}',true);
SELECT ok(public.record_worker_audit_outcome('11111111-1111-4111-8111-111111111111','student_attempt_submit','c1111111-1111-4111-8111-111111111111','failed','state_conflict'),'trusted Worker records a genuine learner operation failure');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM private.security_audit_events WHERE actor_id='11111111-1111-4111-8111-111111111111' AND action='student_attempt_submit' AND target_id='c1111111-1111-4111-8111-111111111111' AND outcome='failed' AND reason_category='state_conflict' AND actor_roles @> ARRAY['student'::public.app_role] AND request_id='dddddddd-dddd-4ddd-8ddd-dddddddddddd' AND transaction_id IS NOT NULL),1,'trusted learner failure retains safe category and actor context');
SELECT * FROM finish();
ROLLBACK;
